using Blazor_CommonModel.App;
using Blazor_CommonModel.Services.DataModel;
using Blazor_CommonModel.Components.Context;
using Blazor_CommonModel.Components.Modal;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using MudBlazor;
using MudBlazor.Services;
using System.Text;
using Microsoft.AspNetCore.Components.Authorization;
using MarketerWeb.Authorization;
using Microsoft.AspNetCore.HttpOverrides;
using Microsoft.AspNetCore.Components.Server.Circuits;


namespace Blazor_CommonModel
{
    
    public class Program 
    {
        
        public static void Main(string[] args)
        {
            ServiceFactory.Get().AddTypesAsync(typeof(Program).Assembly, true);
            ServiceFactory.Get().AddTypesAsync(typeof(MudBlazor.Colors).Assembly, true);
            
            AppProviderService.GetInstance().AddServiceImplementation<IClientAPI, BlazorClientAPI>();
            AppProviderService.GetInstance().AddServiceImplementation<IComponentsFactory<IControlBase>, WebComponentsFactory>();

            CommonProgram.RunTests<Program>(new string[] {  "--no-force"});

            var unit = new AppUnit();
            unit.DoTest(false, false).PrintDocument();


            var builder = WebApplication.CreateBuilder(args);
        
            builder.Services.AddRazorComponents().AddInteractiveServerComponents();

            DeliveryDbContext.ConfigureDeliveryServices(builder.Services, builder.Configuration);
            MonitoringUnit.ConfigureServices(builder.Services);

            ModuleUser.ConfigureServices<DeliveryDbContext>(builder.Configuration, builder.Services);
            ModuleService.ConfigureServices<DeliveryDbContext>(builder.Configuration, builder.Services);

            builder.Services.AddMudServices();
            builder.Services.AddNavMenu();
            // Program.cs
            builder.Services.Configure<ForwardedHeadersOptions>(options =>
            {
                options.ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto;
                // Если используется известный прокси, можно очистить KnownNetworks/Proxies для безопасности
            });
         
            // Authorization
            builder.Services.AddHttpContextAccessor();
            builder.Services.AddCascadingAuthenticationState();
            builder.Services.AddScoped<UserService>();
            builder.Services.AddScoped<AuthStateProvider>();
            builder.Services.AddScoped<AuthenticationStateProvider>(sp => sp.GetRequiredService<AuthStateProvider>());
            builder.Services.AddAuthorizationCore(config =>
            {
                //todo configure authorization
                
            });

            builder.Services.AddScoped<IClientAPI, BlazorClientAPI>();
            builder.Services.AddScoped<IAppModalService, AppModalService>();
            builder.Services.AddScoped<IContextMenuService, ContextMenuService>();
            builder.Services.AddScoped<CircuitHandler, TrackingCircuitHandler>();
            // Также нужен AddHttpContextAccessor
            builder.Services.AddHttpContextAccessor();
            // 4. Добавляем каскадное состояние аутентификации
            // Это критично для работы AuthorizeView. В .NET 8+ используем AddCascadingAuthenticationState.
            //builder.Services.AddCascadingAuthenticationState();

            // 5. Добавляем сервисы для работы с состоянием аутентификации в Blazor
            //builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider<SigninUser<DeliveryDbContext>, UserContext, UserAccount, UserPerson>>();

            ModuleUser.ConfigureServices(builder.Configuration, builder.Services);
            var app = builder.Build();
            app.UseForwardedHeaders();
            app.UseHttpsRedirection();            

            app.UseStaticFiles();
            app.UseAntiforgery();
            //app.UseAuthentication();
            //app.UseAuthentication();

            app.MapRazorComponents<Blazor_CommonModel.Components.App>()
                .AddInteractiveServerRenderMode();  

            app.Run();
        }



        private static void PrintMudComponents()
        {
            ServiceFactory.Get().AddTypes(typeof(MudBadge).Assembly);
            ServiceFactory.Get().AddTypes(typeof(Microsoft.AspNetCore.Components.ComponentBase).Assembly);

            var program = new Program();
            foreach (var ptype in typeof(MudBadge).Assembly.GetRazorComponents())
            {
                program.Info($"<{ptype.GetTypeName()}{ptype.GetParameterNamesLikeXml()}></{ptype.GetTypeName()}>");
            }
        }

        private static void CreateComponents()
        {
            var all = ServiceFactory.Get().GetTypesExtended<AppViewBase>();
            var sb = new StringBuilder();
            HashSet<string> nss = new();
            foreach (var p in all)
            {
                var typeName = p.GetTypeName();
                var ctrlName = typeName.Replace("View", "Control");
                nss.Add(p.Namespace);

                sb.AppendLine($"  }} else if (Type == nameof({typeName})){{");
                sb.AppendLine($"     <{ctrlName} Model=\"@Model\"></{ctrlName}>");
                var body = @"
@code{
    [Parameter]
    public override AppViewBase ViewModel { get; set; }

    protected override async Task OnInitializedAsync(){
        await base.OnInitializedAsync();

        try
        {
            this.BindComponent();            
        }
        catch(Exception ex)
        {
            this.ErrorMessage = ex.Message;
        }
        finally
        {
            this.Initiallized = true;
        }
    }
}
<MudCard>
    @if(!Initiallized)
    {
        <MudProgressCircular>Выполняется инициализация</MudProgressCircular>
    }
    else
    {
        if(ErrorMessage != """" )
        {
            <MudAlert>@ErrorMessage</MudAlert>
        }
        else
        {
            <MudBlazor.Charts.Line></MudBlazor.Charts.Line>
        }
    }
</MudCard>";
                System.IO.File.WriteAllText("C:\\CsProject\\Blazor_CommonModel\\Components\\Shared\\Components\\" + ctrlName + ".razor",
                    (String.IsNullOrWhiteSpace(p.Namespace) ? "" : $"@using {p.Namespace}\n") +
                    $"@inherits WebControlBase<{typeName},{ctrlName}>\n{ctrlName}\n{body}");
            };
            //nss.ToList().Where(l => l!=null && l.Trim().Length > 10).Select(l => "@using " + l + "\n").ToList().ForEach(l => sb.AppendLine(l));
            Console.WriteLine(sb.ToString());
            System.IO.File.WriteAllText("D:\\Components\\_Imports.razor", sb.ToString());
        }

       
    }
}
